		bmi = Math.round(bmi);
		//Paso 4: Descartar la parte fraccionaria del IMC
		int resultBmi = (int) bmi;
		//Paso 5: Imprimir resultados
		System.out.println("El IMC redondeado al entero mas cercano es: " + resultBmi);
	}
}

